'use strict';

const helpers = module.exports;
const utils = require('../../utils');

helpers.noop = function () {};

helpers.toMap = function (data) {
	const map = {};
	for (let i = 0; i < data.length; i += 1) {
		map[data[i]._key] = data[i];
		delete data[i]._key;
	}
	return map;
};

helpers.fieldToString = function (field) {
	if (field === null || field === undefined) {
		return field;
	}

	if (typeof field !== 'string') {
		field = field.toString();
	}
	// if there is a '.' in the field name it inserts subdocument in mongo, replace '.'s with \uff0E
	return field.replace(/\./g, '\uff0E');
};

helpers.serializeData = function (data) {
	const serialized = {};
	for (const [field, value] of Object.entries(data)) {
		if (field !== '') {
			serialized[helpers.fieldToString(field)] = value;
		}
	}
	return serialized;
};

helpers.deserializeData = function (data) {
	const deserialized = {};
	for (const [field, value] of Object.entries(data)) {
		deserialized[field.replace(/\uff0E/g, '.')] = value;
	}
	return deserialized;
};

helpers.valueToString = function (value) {
	return String(value);
};

helpers.buildMatchQuery = function (match) {
	let _match = match;
	if (match.startsWith('*')) {
		_match = _match.substring(1);
	}
	if (match.endsWith('*')) {
		_match = _match.substring(0, _match.length - 1);
	}
	_match = utils.escapeRegexChars(_match);
	if (!match.startsWith('*')) {
		_match = `^${_match}`;
	}
	if (!match.endsWith('*')) {
		_match += '$';
	}
	return _match;
};

'use strict';

const helpers = module.exports;

helpers.noop = function () {};

helpers.execBatch = async function (batch) {
	const results = await batch.exec();
	return results.map(([err, res]) => {
		if (err) {
			throw err;
		}
		return res;
	});
};

helpers.resultsToBool = function (results) {
	for (let i = 0; i < results.length; i += 1) {
		results[i] = results[i] === 1;
	}
	return results;
};

helpers.zsetToObjectArray = function (data) {
	const objects = new Array(data.length / 2);
	for (let i = 0, k = 0; i < objects.length; i += 1, k += 2) {
		objects[i] = { value: data[k], score: parseFloat(data[k + 1]) };
	}
	return objects;
};

