    await client.quit();
    child.execFileSync('redis-cli', ['-s', socket, 'shutdown', 'nosave']);
    if (fs.existsSync(socket)) fs.unlinkSync(socket);
    if (fs.existsSync(pidfile)) fs.unlinkSync(pidfile);
    fs.rmdirSync(dir);
  }
